# Vybe UI upgrade installer
# Run from: C:\Users\Lenovo\Documents\home\user\zip-rick\apps\customer_app

$root = "C:\Users\Lenovo\Documents\home\user\zip-rick\apps\customer_app"
if (-not (Test-Path $root)) { Write-Host "Project folder not found" -ForegroundColor Red; exit 1 }

# backup
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$bk = Join-Path $root "ui_backup_$stamp"
New-Item -ItemType Directory -Force -Path $bk | Out-Null
Copy-Item (Join-Path $root "lib") -Destination (Join-Path $bk "lib") -Recurse -Force
Copy-Item (Join-Path $root "pubspec.yaml") -Destination $bk -Force
Write-Host "Backup saved to $bk" -ForegroundColor Cyan

New-Item -ItemType Directory -Force -Path (Join-Path $root "lib\theme") | Out-Null

# lib\theme\app_theme.dart
$b = ""
$p = Join-Path $root "lib\theme\app_theme.dart"
New-Item -ItemType Directory -Force -Path (Split-Path $p) | Out-Null
[IO.File]::WriteAllBytes($p, [Convert]::FromBase64String($b))
Write-Host "  wrote lib\theme\app_theme.dart" -ForegroundColor Green

